script:
// =========================================
// Set like button icon color if it is liked by the user
// =========================================
const likeIcon = document.getElementById('like-icon');
const likedByMe = Boolean(parseInt(likeIcon?.getAttribute('is-liked')||0))


// Update like icon based on state
if (likeIcon) {
    const svgPath = likeIcon.querySelector('path');
    if (svgPath) {
        if (likedByMe) {
            // Fill the heart when liked
            svgPath.setAttribute('fill', '#ef4444');
        } else {
            // Empty heart when unliked
            svgPath.setAttribute('fill', '#525252');
        }
    }
}

// =========================================
// Set subscribe button label if it is subscribed by the user
// =========================================
document.querySelectorAll('.subscribe-btn').forEach(el=>{
  const textContent = el.querySelector('.__text_block__')


if (textContent){
  textContent.textContent = author.is_subscribed ? 'Subscribed' : 'Subscribe';
}})
// =========================================
// Handle subscribe button interactivity
// =========================================
async function toggleSubscribe(publication, btn) {
    const payload = {
        doc: {
            doctype: "Cafe Subscription",
            publication: publication
            // user auto-set by document hook
        }
    };

    try {
        const response = await fetch('/api/resource/Cafe Subscription', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify(payload)
        });

        const result = await response.json();

        // Check if unsubscribed via flag
        const isSubscribed = !result.data.subscribed_by_me;

        // Update button
      document.querySelectorAll('.subscribe-btn').forEach(el=>{
        const textContent = el.querySelector('.__text_block__')


      if (textContent){
        textContent.textContent = isSubscribed ? 'Subscribed' : 'Subscribe';
      }
      });


        return result;

    } catch (error) {
        console.error('Error:', error);
        throw error;
    }
}

document.querySelectorAll('.subscribe-btn').forEach(el=>{
    el.onclick = function() {
        toggleSubscribe('My Publication', this);
    };
});
